from pathlib import Path
import json

p=Path(__file__).parent/'2026.10.12 Contract PECH continut.json'
d=json.loads(p.read_text(encoding='utf-8'))
def section(prefix,paragraphs=None,table=None):
    s=next(x for x in d['sections'] if x['title'].startswith(prefix))
    if paragraphs is not None:s['paragraphs']=paragraphs
    if table is not None:s['table']=table
    return s
def table(headers,rows):return {'headers':headers,'rows':rows}

s=section('Vertragsparteien')
s['paragraphs'][0]='Auftraggeberin (AG): A&C Wohnart Immobilien GmbH, FN 668224h, Handelsgericht Wien, UID ATU83086125; Geschäftsanschrift Schallergasse 35, 1120 Wien; vertreten durch Geschäftsführer Cosmin-Adrian Covaciu; E-Mail office@ac-wohnart.at; Telefon +43 665 67055045. Eine gegebenenfalls abweichende Rechnungsanschrift wird vor Unterzeichnung bestätigt.'
s=section('§ 1')
s['paragraphs'][1]='(2) Vertragsbestandteile in absteigender Rangfolge sind: spätere beiderseits ausdrücklich vereinbarte Änderungen beziehungsweise eine bei Unterzeichnung beiderseits gezeichnete Abweichungsliste, jeweils nur hinsichtlich der konkret geänderten Punkte; dieser beiderseits unterzeichnete Werkvertrag einschließlich der Anlagen 1 bis 4; die gemeinsam bestätigte Plan- und Dokumentenliste; das unveränderte Originalangebot Dr. PECH 2026-470/AN01 vom 2026.09.17 als Anlage 5. Die historischen Beträge bleiben dokumentiert; alle ausdrücklichen Erweiterungen dieses Vertrages gehen Einschränkungen der ursprünglichen Leistungsbeschreibung vor.'
s=section('§ 3')
s['paragraphs'][1]=s['paragraphs'][1].replace('Ertüchtigung der Tram- und Dippelbaumdecken, Auflager und Deckenränder;', 'Ertüchtigung der Tram- und Dippelbaumdecken, Auflager und Deckenränder sowie die im genehmigten beziehungsweise gemeinsam bestätigten Projekt vorgesehene neue Stahlbeton-Verbunddecke über dem dritten Obergeschoss;')
s=section('§ 8')
s['paragraphs'][0]='(1) Position 06 umfasst die vollständigen Schlussunterlagen sowie ausdrücklich die erstmalige Erstellung beziehungsweise fachgerechte Vervollständigung des Bauwerksbuchs für das gesamte bestehende Wohngebäude und alle durch das Vorhaben neuen Bauteile und Eingriffe. Ein Bauwerksbuch nur für den Dachgeschossausbau oder nur für neu errichtete Bauteile genügt nicht. Der AN ermittelt und dokumentiert die im konkreten Fall erforderliche gesetzliche Grundlage, den Umfang, die befugte erstellende Person und die zeitlich maßgeblichen Pflichten nach § 128a BO für Wien in der anwendbaren Fassung. Das tatsächliche Errichtungsjahr wird anhand geeigneter Unterlagen festgestellt; eine bestimmte Übergangsfrist wird nicht allein aus der Bezeichnung Gründerzeithaus abgeleitet.'
s['paragraphs'].insert(1,'(1a) Die für Bauwerksbuch und zugehörige Prüfungen benannten Personen müssen die gesetzlich vorgeschriebene Befugnis und Unabhängigkeit erfüllen. Die erforderliche Unabhängigkeit von Bauwerber, Bauführer und Eigentümer sowie von einschlägigen Dienst- und Organschaftsverhältnissen wird vor Beauftragung der jeweiligen Funktion geprüft und schriftlich dokumentiert. Eine interne Qualitätsprüfung ersetzt diese gesetzlichen Voraussetzungen nicht. Der AN organisiert erforderliche geeignete unabhängige Personen innerhalb der vereinbarten Gesamtpauschale.')
